def mapfig(sites,segments=(),title='Site map',bounds=(0,12,0,12)):
 x0,x1,y0,y1=bounds
 def p(x,y):return (70+460*(x-x0)/(x1-x0),300-240*(y-y0)/(y1-y0))
 es=[txt((65,25),title,16),line(p(x0,y0),p(x1,y0)),line(p(x0,y0),p(x0,y1)),txt((500,345),'x (km)'),txt((16,47),'y (km)')]
 for k in range(7):
  x=x0+(x1-x0)*k/6;y=y0+(y1-y0)*k/6;es +=[txt((p(x,y0)[0]-5,320),n(x),11),txt((22,p(x0,y)[1]+4),n(y),11)]
 for a,b in segments:es +=[line(p(*a),p(*b),'#0f766e')]
 for x,y,z in sites:es +=[dot(p(x,y)),txt((p(x,y)[0]+7,p(x,y)[1]-9),z,13)]
 return svg(es)
