 return svg([line(ps[u],ps[v],dash=(u,v) in [(2,3),(3,0),(3,7)]) for u,v in edges]+[line(ps[0],ps[6],'#b45309'),txt((245,310),f'{a} m'),txt((455,260),f'{b} m'),txt((75,200),f'{h} m'),txt((100,305),'A'),txt((505,40),'G'),txt((390,25),'Perspective diagram',12)])
